"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { ToggleGroup as ToggleGroupPrimitive } from "@base-ui/react/toggle-group";
import { type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { wellInset } from "./_shared";
import { toggleVariants } from "./toggle";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

const ToggleGroupContext = React.createContext<
  VariantProps<typeof toggleVariants>
>({});

/**
 * Paddock ToggleGroup: a view switch. A row of segments in one recessed
 * grey track; the pressed segment rises as a white segment. The group
 * passes its variant and size to every item.
 */
function ToggleGroup({
  className,
  variant,
  size,
  children,
  ...props
}: WithClassName<ToggleGroupPrimitive.Props<string>> &
  VariantProps<typeof toggleVariants>) {
  return (
    <ToggleGroupPrimitive
      data-slot="toggle-group"
      className={cn(
        "inline-flex flex-wrap items-center gap-0.5 rounded-md p-1",
        wellInset,
        "data-[orientation=vertical]:flex-col data-[orientation=vertical]:items-stretch data-[orientation=vertical]:rounded-lg",
        className,
      )}
      {...props}
    >
      <ToggleGroupContext.Provider value={{ variant, size }}>
        {children}
      </ToggleGroupContext.Provider>
    </ToggleGroupPrimitive>
  );
}
ToggleGroup.displayName = "ToggleGroup";

/** One option in the track; flat until pressed, unless the group names another variant. */
function ToggleGroupItem({
  className,
  variant,
  size,
  ...props
}: WithClassName<TogglePrimitive.Props<string>> &
  VariantProps<typeof toggleVariants>) {
  const context = React.useContext(ToggleGroupContext);
  const resolved = context.variant || variant || "inset";
  const resolvedSize = context.size || size;

  return (
    <TogglePrimitive
      data-slot="toggle-group-item"
      className={cn(
        toggleVariants({ variant: resolved, size: resolvedSize }),
        resolved === "inset" && (!resolvedSize || resolvedSize === "default") && "h-8 px-3.5",
        className,
      )}
      {...props}
    />
  );
}
ToggleGroupItem.displayName = "ToggleGroupItem";

export { ToggleGroup, ToggleGroupItem };
